Algoritmo Intercambio
  Definir a Como Entero <- 1;
  Definir b Como Entero <- 2;
  Definir auxiliar Como Entero;
  auxiliar <- a;
  a <- b;
  b <- auxiliar;
  Escribir a, " ", b;
FinAlgoritmo

Algoritmo Tipos
  Definir x Como Entero <- 1;
  x <- "uno";
  Escribir x;
FinAlgoritmo

Algoritmo Fuera
  Dimension notas[3] Como Entero;
  notas[3] <- 1;
FinAlgoritmo
